import random


def generate(seed: int = 0) -> list[str]:
    """All generated arguments stay within the statement bounds and follow the problem guarantees."""
    r = random.Random(seed)
    cases = [([[1, 3], [2, 2], [3, 1]], 4)]
    seen = set()
    while len(cases) < 600:
        n = r.randint(1, 15)
        boxes = [[r.randint(1, 20), r.randint(1, 100)] for _ in range(n)]
        size = r.randint(1, 100)
        key = (tuple(map(tuple, boxes)), size)
        if key not in seen:
            seen.add(key)
            cases.append((boxes, size))
    return [f"candidate(boxTypes={a!r}, truckSize={s})" for a, s in cases]


